from pathlib import Path
import hashlib, json, shutil
root = Path('/work')
records = {}
for name, src in [('baseline', root/'crate'), ('fixed', root/'fixed')]:
    dest = root/'tmp'/f'{name}-control'
    shutil.copytree(src, dest, ignore=shutil.ignore_patterns('target', '.git'))
    manifest = {str(f.relative_to(src)): hashlib.sha256(f.read_bytes()).hexdigest() for f in sorted(src.rglob('*')) if f.is_file()}
    records[name] = manifest
    assert all((dest/k).is_file() and hashlib.sha256((dest/k).read_bytes()).hexdigest() == v for k,v in manifest.items())
(root/'prepared/logs/source-manifests.json').write_text(json.dumps(records, indent=2)+'\n')
